# ado-cop.ps1: runs the rules in rules.json against Azure DevOps projects.
# Run with no arguments (F5) and Main supplies everything, with the PAT read from
# Windows Credential Manager under the entry the rules file names. The pipeline passes
# every value as a parameter instead.
# Read-only: Invoke-AdoGet is the only network call and it hard-codes GET.
# Generated by AI. No copyright claimed. Public domain under the Unlicense; see LICENSE.
param(
  [string]$AdoOrgUrl,
  [string]$AdoToken,
  [string[]]$Projects,
  [string]$RulesFile,
  [string]$OutputPath,
  [string]$PatEntryName   # Windows Credential Manager entry that holds the PAT; not the PAT itself
)

function Main {
  if (-not $env:TF_BUILD) { try { Clear-Host } catch { } }

  # Local defaults. Anything passed on the command line (the pipeline does this) wins.
  $script:AdoOrgUrl         = Coalesce $AdoOrgUrl      "https://dev.azure.com/<organization>/"
  $script:AdoCredentialName = $PatEntryName   # empty means the PatEntryName setting in the rules file, then ado-cop-PAT
  $script:RulesFile         = Coalesce $RulesFile      (Join-Path $PSScriptRoot "rules.json")
  $script:ReportPath        = Join-Path $PSScriptRoot "ado-cop.md"   # overwritten each run
  $script:AdoToken          = $AdoToken   # pipeline only; empty means use Credential Manager

  # Test-AdoConnection     # uncomment to confirm the PAT works and list visible projects

  # The projects to inspect. Pass -Projects or put the local default list here.
  # The results stay in $AdoCop after the run.
  $targets = if ($Projects) { @($Projects) } else { @() }
  if ($targets.Count -eq 0) { throw "Pass -Projects <name>[,<name>] or set the default list in the Main function of ado-cop.ps1." }

  $script:AdoCop = Invoke-AdoCop -Projects $targets -OutputPath $OutputPath
}

# API versions. 7.1 is current GA; Analytics is still on a preview tag.
$script:ApiVersion          = "7.1"
$script:AnalyticsApiVersion = "v4.0-preview"

# Status values a rule can report. The report maps them to glyphs.
$script:StatusPass    = "Pass"
$script:StatusWarning = "Warning"
$script:StatusError   = "Error"

# =============================================================================
# Windows Credential Manager (CredRead only). Compiled on first use so the script
# also loads on a Linux build agent, where the PAT arrives as -AdoToken instead.
# =============================================================================

function Initialize-AdoCredMan {
  if ("AdoCredMan" -as [type]) { return }
  $onWindows = ($PSVersionTable.PSVersion.Major -lt 6) -or $IsWindows
  if (-not $onWindows) {
    throw "Windows Credential Manager is only available on Windows. Pass -AdoToken instead."
  }
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;

public static class AdoCredMan
{
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct CREDENTIAL
    {
        public uint Flags;
        public uint Type;
        public string TargetName;
        public string Comment;
        public System.Runtime.InteropServices.ComTypes.FILETIME LastWritten;
        public uint CredentialBlobSize;
        public IntPtr CredentialBlob;
        public uint Persist;
        public uint AttributeCount;
        public IntPtr Attributes;
        public string TargetAlias;
        public string UserName;
    }

    [DllImport("advapi32.dll", EntryPoint = "CredReadW", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern bool CredRead(string target, uint type, uint flags, out IntPtr credential);

    [DllImport("advapi32.dll")]
    private static extern void CredFree(IntPtr credential);

    private const uint CRED_TYPE_GENERIC = 1;
    private const int ERROR_NOT_FOUND = 1168;

    public static string Read(string target)
    {
        IntPtr ptr;
        if (!CredRead(target, CRED_TYPE_GENERIC, 0, out ptr))
        {
            int err = Marshal.GetLastWin32Error();
            if (err == ERROR_NOT_FOUND) return null;
            throw new System.ComponentModel.Win32Exception(err);
        }
        try
        {
            CREDENTIAL cred = (CREDENTIAL)Marshal.PtrToStructure(ptr, typeof(CREDENTIAL));
            if (cred.CredentialBlobSize == 0) return string.Empty;
            return Marshal.PtrToStringUni(cred.CredentialBlob, (int)cred.CredentialBlobSize / 2);
        }
        finally
        {
            CredFree(ptr);
        }
    }
}
"@
}

function Get-AdoOrgName {
  # Parses the organization name out of $script:AdoOrgUrl.
  $url = [string]$script:AdoOrgUrl
  if ([string]::IsNullOrWhiteSpace($url)) {
    throw "Set `$script:AdoOrgUrl in the Main function of ado-cop.ps1 (or pass -AdoOrgUrl) to your organization URL."
  }
  $url = $url.Trim()
  if (-not $url.EndsWith('/')) { $url += '/' }
  if ($url -match '^https://dev\.azure\.com/([^/]+)/$') { return $Matches[1] }
  if ($url -match '^https://([^./]+)\.visualstudio\.com/$') { return $Matches[1] }
  throw "Unrecognized organization URL '$url'. Expected https://dev.azure.com/{org}/ or https://{org}.visualstudio.com/"
}

function Get-AdoCredentialName {
  # -PatEntryName wins; otherwise the PatEntryName setting in the rules file; otherwise ado-cop-PAT.
  if (-not [string]::IsNullOrWhiteSpace($script:AdoCredentialName)) { return $script:AdoCredentialName.Trim() }
  if (-not $script:Rules) { $script:Rules = Read-RuleFile $script:RulesFile }
  return [string](Get-Setting 'PatEntryName' 'ado-cop-PAT')
}

function Get-AdoPat {
  # A token passed on the command line (pipeline) wins over Credential Manager.
  if (-not [string]::IsNullOrWhiteSpace($script:AdoToken)) { return $script:AdoToken.Trim() }
  $target = Get-AdoCredentialName
  Initialize-AdoCredMan
  $pat = [AdoCredMan]::Read($target)
  if ([string]::IsNullOrWhiteSpace($pat)) {
    throw "No PAT found. Add a Windows generic credential named '$target' (see README.md) or pass -AdoToken."
  }
  return $pat.Trim()
}

# =============================================================================
# Connection
# =============================================================================

function Connect-Ado {
  # Resolves the organization URLs and builds the auth header. Called automatically.
  $org = Get-AdoOrgName

  $script:Org           = $org
  $script:CoreBase      = "https://dev.azure.com/$org/"
  $script:GraphBase     = "https://vssps.dev.azure.com/$org/"
  $script:AnalyticsBase = "https://analytics.dev.azure.com/$org/"
  $script:ReleaseBase   = "https://vsrm.dev.azure.com/$org/"
  $script:FeedsBase     = "https://feeds.dev.azure.com/$org/"
  $script:ExtMgmtBase   = "https://extmgmt.dev.azure.com/$org/"
  $script:EntitlementBase = "https://vsaex.dev.azure.com/$org/"

  $pat = Get-AdoPat
  $bytes = [Text.Encoding]::ASCII.GetBytes(":" + $pat)
  $script:AdoHeaders = @{
    Authorization = "Basic " + [Convert]::ToBase64String($bytes)
    Accept        = "application/json"
  }
  $pat = $null
  $script:Connected = $true
}

function Test-AdoConnection {
  # Confirms the PAT authenticates and shows the identity it resolves to.
  Connect-Ado
  $data = Invoke-AdoGet -Uri ($script:CoreBase + "_apis/connectionData?api-version=$($script:ApiVersion)-preview.1")
  $user = $data.authenticatedUser
  $account = $null
  try { $account = $user.properties.Account.'$value' } catch { }
  if (-not $account) { $account = $user.id }
  Write-Host ("Connected to {0} as {1} ({2})" -f $script:Org, $user.providerDisplayName, $account) -ForegroundColor Green
  $projects = Invoke-AdoGet -Uri ($script:CoreBase + "_apis/projects?api-version=$($script:ApiVersion)") -AllPages
  Write-Host ("{0} project(s) visible: {1}" -f @($projects).Count, (($projects | Sort-Object name | ForEach-Object { $_.name }) -join ", "))
}

# =============================================================================
# HTTP: the ONLY function that talks to Azure DevOps. GET is hard-coded.
# =============================================================================

function Invoke-AdoGet {
  # Issues an HTTP GET and returns the parsed JSON body. -AllPages follows
  # continuation tokens and OData nextLink and returns the concatenated "value"
  # arrays. -Raw returns the body as text.
  [CmdletBinding()]
  param(
    [Parameter(Mandatory = $true)][string]$Uri,
    [switch]$AllPages,
    [switch]$Raw
  )

  if (-not $script:Connected) { Connect-Ado }

  $collected = New-Object System.Collections.Generic.List[object]
  $nextUri = $Uri
  $guard = 0

  while ($nextUri) {
    $guard++
    if ($guard -gt 500) { throw "Paging guard tripped for $Uri" }

    # The verb below is the only verb this script ever uses. Transient server answers
    # (429 throttled, 502/503/504 unavailable; Analytics gives these now and then) are
    # retried up to three times with a short back-off before the rule sees an error.
    $attempt = 0
    while ($true) {
      $attempt++
      try {
        $response = Invoke-WebRequest -Uri $nextUri -Headers $script:AdoHeaders -Method Get -UseBasicParsing -ErrorAction Stop
        break
      } catch {
        $status = $null
        try { $status = [int]$_.Exception.Response.StatusCode } catch { }
        if ($status -in 429, 502, 503, 504 -and $attempt -le 3) {
          $delay = 2 * $attempt
          Write-Host ("        HTTP {0}; retrying in {1}s (attempt {2} of 3)" -f $status, $delay, $attempt) -ForegroundColor DarkYellow
          Start-Sleep -Seconds $delay
          continue
        }
        # Some endpoints still require "-preview" on the api-version. Azure DevOps says
        # so explicitly; when it does, retry once with the preview tag appended.
        $bodyText = Get-AdoErrorBody $_
        if ($bodyText -like '*VssInvalidPreviewVersionException*' -and $nextUri -match 'api-version=([\d.]+)(&|$)') {
          $retryUri = $nextUri -replace 'api-version=([\d.]+)(&|$)', 'api-version=$1-preview$2'
          Write-Verbose "Retrying with preview api-version: $retryUri"
          $response = Invoke-WebRequest -Uri $retryUri -Headers $script:AdoHeaders -Method Get -UseBasicParsing -ErrorAction Stop
          break
        }
        # Put the server's own message in the exception so a rule's error result
        # says what went wrong (missing scope, bad query) rather than just "400".
        throw (Get-AdoErrorMessage $_ $bodyText)
      }
    }

    $contentType = ""
    foreach ($k in $response.Headers.Keys) {
      if ($k -ieq 'Content-Type') { $contentType = [string](@($response.Headers[$k])[0]) }
    }
    if ($contentType -like 'text/html*') {
      throw "Azure DevOps returned an HTML sign-in page instead of JSON. The PAT is missing, expired, or lacks access. ($nextUri)"
    }

    if ($Raw) { return $response.Content }

    $body = ConvertFrom-AdoJson $response.Content
    if (-not $AllPages) { return $body }

    if ($null -ne $body.PSObject.Properties['value']) {
      foreach ($item in @($body.value)) { $collected.Add($item) }
    } elseif ($null -ne $body.PSObject.Properties['members']) {
      foreach ($item in @($body.members)) { $collected.Add($item) }
    } else {
      $collected.Add($body)
    }

    $nextUri = $null

    # Continuation token in a response header (Core, Graph, Build, Test Plans)
    $token = $null
    foreach ($k in $response.Headers.Keys) {
      if ($k -ieq 'x-ms-continuationtoken') { $token = [string](@($response.Headers[$k])[0]) }
    }
    # Continuation token in the body (Member Entitlement Management)
    if (-not $token -and $null -ne $body.PSObject.Properties['continuationToken'] -and $body.continuationToken) {
      $token = [string]$body.continuationToken
    }
    if ($token) {
      $sep = '&'
      if ($Uri -notlike '*?*') { $sep = '?' }
      $nextUri = $Uri + $sep + "continuationToken=" + [uri]::EscapeDataString($token)
    }
    # OData nextLink (Analytics)
    if ($null -ne $body.PSObject.Properties['@odata.nextLink'] -and $body.'@odata.nextLink') {
      $nextUri = [string]$body.'@odata.nextLink'
    }
  }

  return ,$collected.ToArray()
}

function Get-AdoErrorBody($ErrorRecord) {
  # Returns the response body text from a failed Invoke-WebRequest, on both
  # PowerShell 7 (ErrorDetails) and Windows PowerShell 5.1 (response stream).
  try {
    if ($ErrorRecord.ErrorDetails -and $ErrorRecord.ErrorDetails.Message) { return [string]$ErrorRecord.ErrorDetails.Message }
    $resp = $ErrorRecord.Exception.Response
    if ($resp -and ($resp -is [System.Net.HttpWebResponse])) {
      $stream = $resp.GetResponseStream()
      if ($stream) {
        $reader = New-Object System.IO.StreamReader($stream)
        $text = $reader.ReadToEnd()
        $reader.Dispose()
        return $text
      }
    }
  } catch { }
  return [string]$ErrorRecord.Exception.Message
}

function Get-AdoErrorMessage($ErrorRecord, [string]$BodyText) {
  # "HTTP 400: VS403522: The property 'AreaPath' is not available..." when the body
  # is the usual Azure DevOps JSON error; otherwise the raw exception message.
  $status = $null
  try { $status = [int]$ErrorRecord.Exception.Response.StatusCode } catch { }
  $message = $null
  try {
    $parsed = $BodyText | ConvertFrom-Json
    if ($parsed.error -and $parsed.error.message) { $message = [string]$parsed.error.message }
    elseif ($parsed.message) { $message = [string]$parsed.message }
  } catch { }
  if (-not $message) { $message = [string]$ErrorRecord.Exception.Message }
  if ($status) { return "HTTP ${status}: $message" }
  return $message
}

function ConvertFrom-AdoJson([string]$Content) {
  # Some payloads (work item types) carry a property whose name is an empty
  # string, which PowerShell 7's parser refuses. Rename it and retry.
  try {
    return ($Content | ConvertFrom-Json)
  } catch {
    $patched = $Content -replace '"\s*"\s*:', '"_empty_":'
    return ($patched | ConvertFrom-Json)
  }
}

function Get-AdoAllProjects {
  if ($null -eq $script:ProjectCache) {
    # No @() here: -AllPages already returns an array, and @() would nest it.
    $script:ProjectCache = Invoke-AdoGet -Uri ($script:CoreBase + "_apis/projects?`$top=1000&api-version=$($script:ApiVersion)") -AllPages
  }
  return $script:ProjectCache
}

# =============================================================================
# Rules engine
# =============================================================================

function Read-RuleFile([string]$Path) {
  # Keys shaped XXX###_Name set to true are rules to run; Test_Rule names a single
  # rule to run instead; everything else is a setting rules read with Get-Setting.
  if (-not (Test-Path $Path)) { throw "Rules file not found: $Path" }
  $json = Get-Content $Path -Raw | ConvertFrom-Json

  $settings = [ordered]@{}
  $active   = New-Object System.Collections.Generic.List[string]
  $testRule = ""

  foreach ($prop in $json.PSObject.Properties) {
    $name  = ([string]$prop.Name).Trim()
    $value = $prop.Value
    if ($name -eq 'Test_Rule') {
      if ($value -is [string]) { $testRule = $value.Trim() }
    } elseif ($name -match '^[A-Z]{3}\d{3}_') {
      if ($value) { $active.Add($name) }
    } else {
      if ($value -is [string]) { $value = $value.Trim() }
      $settings[$name] = $value
    }
  }

  return [pscustomobject]@{
    Path     = $Path
    Settings = $settings
    Active   = $active.ToArray()
    TestRule = $testRule
  }
}

function Get-Setting([string]$Name, $Default = $null) {
  # Reads a non-rule key from the rules JSON, with a default when it is absent or blank.
  $settings = $script:Rules.Settings
  if ($settings.Contains($Name)) {
    $value = $settings[$Name]
    if ($null -ne $value -and -not ($value -is [string] -and [string]::IsNullOrWhiteSpace($value))) { return $value }
  }
  return $Default
}

function Get-SettingList([string]$Name, [string[]]$Default = @()) {
  # As Get-Setting, but splits a comma-separated string into trimmed, non-empty parts.
  $value = Get-Setting $Name
  if ($null -eq $value) { return $Default }
  if ($value -is [string]) {
    return @($value -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
  }
  return @($value)
}

function Get-RuleCode([string]$FunctionName) {
  # Rule_WRK200_FeaturesHaveParentEpic -> WRK200
  return ($FunctionName -replace '^Rule_([A-Z]{3}\d{3})_.*$', '$1')
}

function Get-RuleTitle([string]$RuleName) {
  # WRK200_FeaturesHaveParentEpic -> "WRK200: Features have parent epic"
  $trimmed = $RuleName -replace '^Rule_', ''
  $code, $namePart = $trimmed -split '_', 2
  if (-not $namePart) { return $trimmed }
  $words = [regex]::Replace($namePart, '(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])', ' ')
  $sentence = $words.ToLower()
  $sentence = $sentence.Substring(0, 1).ToUpper() + $sentence.Substring(1)
  # Work item type names keep their capitals; states stay lower case.
  $sentence = $sentence -replace '\bepic', 'Epic' -replace '\bfeature', 'Feature' -replace '\bstor(y|ies)\b', 'Stor$1' `
    -replace '\bbug', 'Bug' -replace '\btask', 'Task' -replace '\binitiative', 'Initiative' `
    -replace '\buser (Stor)', 'User $1' -replace '\bproduct backlog item', 'Product Backlog Item' `
    -replace '\bpi\b', 'PI' -replace '\bsafe\b', 'SAFe'
  return "${code}: $sentence"
}

function Add-Result {
  # Records what a rule found for one project. Description is the full finding for the
  # console; Note is the short version for the report table (defaults to Description).
  # Items is an optional list of objects the JSON keeps in full.
  param(
    [Parameter(Mandatory = $true)]$Project,
    [Parameter(Mandatory = $true)][string]$Rule,
    [Parameter(Mandatory = $true)][string]$Status,
    [Parameter(Mandatory = $true)][string]$Description,
    [string]$Note,
    [object[]]$Items = @()
  )
  if ([string]::IsNullOrWhiteSpace($Note)) { $Note = $Description }
  $script:Results.Add([pscustomobject]@{
    Project     = [string]$Project.name
    Rule        = $Rule
    Title       = $script:RuleTitles[$Rule]
    Status      = $Status
    Description = $Description
    Note        = $Note
    Count       = @($Items).Count
    Items       = @($Items)
  })
  # One line per result on the console, under the "Rule:" heading Invoke-AdoCop prints.
  $color = switch ($Status) { 'Pass' { 'Green' } 'Warning' { 'Yellow' } default { 'Red' } }
  $prefix = if ($script:TargetCount -gt 1) { "$($Project.name): " } else { "" }
  Write-Host ("{0,-7} {1}{2}" -f $Status, $prefix, $Description) -ForegroundColor $color
  # In a pipeline, each warning and error also appears on the run summary, unless
  # PipelineWarnings (setting) is false: then only errors do, since findings are the report's job.
  $raise = if ($Status -eq $script:StatusError) { $true } elseif ($Status -eq $script:StatusWarning) { [bool](Get-Setting 'PipelineWarnings' $true) } else { $false }
  if ($env:TF_BUILD -and $raise) {
    $type = if ($Status -eq $script:StatusError) { 'error' } else { 'warning' }
    Write-Host "##vso[task.logissue type=$type]$($Project.name) $Rule $Description"
  }
}

function Invoke-Rule($RuleName, $Project) {
  $functionName = "Rule_" + $RuleName
  $code = Get-RuleCode $functionName
  $script:RuleTitles[$code] = Get-RuleTitle $RuleName
  if (-not (Get-Command $functionName -ErrorAction SilentlyContinue)) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusError -Description "Function $functionName not found in ado-cop.ps1."
    return
  }
  try {
    & $functionName -Project $Project
  } catch {
    Add-Result -Project $Project -Rule $code -Status $script:StatusError -Description "$code failed: $($_.Exception.Message)"
  }
}

function Invoke-AdoCop {
  # Runs the active rules against the given projects, writes the Markdown report
  # (default ado-cop.md next to the script) plus a JSON dump next to it, and
  # returns the result objects, one per project per rule.
  [CmdletBinding()]
  param(
    [Parameter(Mandatory = $true)][string[]]$Projects,
    [string]$OutputPath
  )

  $script:Rules        = Read-RuleFile $script:RulesFile   # before Connect-Ado: it may name the PAT entry
  Connect-Ado
  $script:ProjectCache = $null
  $script:PairsCache   = @{}
  $script:ProcessMap   = $null
  $script:TeamCache    = @{}
  $script:TypeFieldCache = @{}
  $script:EntitlementCache = $null
  $script:ProcessIdCache   = @{}
  $script:ProcessTypeCache = @{}
  $script:TypeStateCache   = @{}
  $script:TeamBacklogCache = @{}
  $script:QueryPathCache   = @{}
  $script:BacklogLevelCache = @{}
  $script:Results      = New-Object System.Collections.Generic.List[object]
  $script:RuleTitles   = @{}

  $ruleNames = @($script:Rules.Active)
  if ($script:Rules.TestRule) {
    $ruleNames = @($script:Rules.TestRule)
    Write-Host ("Test_Rule is set: running only {0}" -f $script:Rules.TestRule) -ForegroundColor Yellow
  }
  if ($ruleNames.Count -eq 0) { throw "No active rules in $($script:RulesFile)." }

  # Resolve requested names against the organization
  $available = @(Get-AdoAllProjects)
  # Accept 'A','B' (PowerShell), "A,B" (pwsh -File or cmd), and stray quotes from either.
  $requested = @($Projects | ForEach-Object { $_ -split ',' } |
    ForEach-Object { $_.Trim().Trim("'", '"').Trim() } | Where-Object { $_ } | Select-Object -Unique)
  $targets = New-Object System.Collections.Generic.List[object]
  $missing = New-Object System.Collections.Generic.List[string]
  foreach ($name in $requested) {
    $match = $available | Where-Object { $_.name -ieq $name } | Select-Object -First 1
    if ($match) { $targets.Add($match) } else { $missing.Add($name) }
  }
  if ($missing.Count -gt 0) {
    Write-Host ("Not found in {0} (check spelling or PAT project access): {1}" -f $script:Org, ($missing -join ', ')) -ForegroundColor Yellow
  }
  if ($targets.Count -eq 0) { throw "No matching projects to inspect." }

  $started = Get-Date
  $script:TargetCount = $targets.Count
  $script:Targets     = $targets.ToArray()
  Write-Host ("Started {0}" -f $started.ToString('HH:mm:ss')) -ForegroundColor Cyan
  Write-Host ""
  Write-Host ("Running rules from {0}" -f (Split-Path -Leaf $script:RulesFile))
  foreach ($ruleName in $ruleNames) {
    Write-Host ""
    Write-Host ("Rule: {0}" -f (Get-RuleTitle $ruleName)) -ForegroundColor Cyan
    foreach ($project in $targets) {
      Invoke-Rule -RuleName $ruleName -Project $project
    }
  }
  Write-Host ""

  # Write outputs
  if (-not $OutputPath) {
    $OutputPath = $script:ReportPath
    if ([string]::IsNullOrWhiteSpace($OutputPath)) { $OutputPath = Join-Path $PSScriptRoot "ado-cop.md" }
  }
  $outFolder = Split-Path -Parent $OutputPath
  if ($outFolder -and -not (Test-Path $outFolder)) { New-Item -ItemType Directory -Path $outFolder | Out-Null }
  # The Markdown report is always written. The item log (WriteLog) and the JSON for
  # tooling (WriteJson) are settings in the rules file, both off unless switched on.
  # LF line endings: pasted into an Azure DevOps wiki page, CRLF text gains a blank line
  # after every row, which breaks every table into loose paragraphs.
  $markdown = (New-AdoCopReport -Results $script:Results -Missing $missing -Started $started) -replace "`r`n", "`n"
  [IO.File]::WriteAllText($OutputPath, $markdown, [Text.UTF8Encoding]::new($false))
  $writeLog  = [bool](Get-Setting 'WriteLog' $false)
  $writeJson = [bool](Get-Setting 'WriteJson' $false)
  $logPath  = [IO.Path]::ChangeExtension($OutputPath, '.log')
  $jsonPath = [IO.Path]::ChangeExtension($OutputPath, '.json')
  if ($writeLog)  { [IO.File]::WriteAllText($logPath, ((New-AdoCopLog -Results $script:Results -Started $started) -replace "`r`n", "`n"), [Text.UTF8Encoding]::new($false)) }
  if ($writeJson) { $script:Results | ConvertTo-Json -Depth 8 | Set-Content -Path $jsonPath -Encoding UTF8 }

  $warnings = @($script:Results | Where-Object { $_.Status -eq $script:StatusWarning }).Count
  $errors   = @($script:Results | Where-Object { $_.Status -eq $script:StatusError }).Count
  $finished = Get-Date
  Write-Host ("Report: {0}  ({1} pass, {2} warning, {3} error)" -f $OutputPath, ($script:Results.Count - $warnings - $errors), $warnings, $errors)
  if ($writeLog)  { Write-Host ("Log:    {0}" -f $logPath) }
  if ($writeJson) { Write-Host ("JSON:   {0}" -f $jsonPath) }
  Write-Host ""
  Write-Host ("Ending {0}" -f $finished.ToString('HH:mm:ss')) -ForegroundColor Cyan
  # The run's colour. By default any warning or error makes it amber (succeeded with issues).
  # With PipelineWarnings false, warnings leave it green and an error (a rule that could not
  # run) turns it red, so the colour says whether the check itself worked.
  if ($env:TF_BUILD) {
    if ([bool](Get-Setting 'PipelineWarnings' $true)) {
      if (($warnings + $errors) -gt 0) { Write-Host "##vso[task.complete result=SucceededWithIssues;]$warnings warning(s), $errors error(s)" }
    } elseif ($errors -gt 0) {
      Write-Host "##vso[task.complete result=Failed;]$errors rule(s) could not run"
    }
  }
  return $script:Results.ToArray()
}

# =============================================================================
# Shared helpers for rules
# =============================================================================

function ConvertTo-ODataString([string]$Value) {
  # Escapes a value for use inside single quotes in an OData filter.
  return $Value -replace "'", "''"
}

function Get-AnalyticsWorkItems {
  # Reads work items for one project from the Analytics OData service (GET).
  # Filter is appended to the project filter, e.g. "WorkItemType eq 'Feature'".
  # Area and iteration paths are not columns; get them through Expand, e.g.
  # "Area(`$select=AreaPath)", and read $item.Area.AreaPath. Do not expand Parent
  # on the org-level endpoint: it 403s unless the PAT can see every project.
  param(
    [Parameter(Mandatory = $true)]$Project,
    [Parameter(Mandatory = $true)][string]$Filter,
    [string]$Select = "WorkItemId,Title,WorkItemType,State",
    [string]$Expand
  )
  $projectFilter = "Project/ProjectName eq '$(ConvertTo-ODataString $Project.name)'"
  $uri = $script:AnalyticsBase + "_odata/$($script:AnalyticsApiVersion)/WorkItems?" +
         "`$filter=$projectFilter and ($Filter)&`$select=$Select"
  if ($Expand) { $uri += "&`$expand=$Expand" }
  $rows = Invoke-AdoGet -Uri $uri -AllPages
  return ,@($rows)
}

function Get-WorkItemFields {
  # Reads a few fields for a set of work item IDs through the work items REST API
  # (GET, 200 IDs per call). Works across projects. Returns a hashtable keyed by
  # ID; IDs the PAT cannot read are simply absent.
  param(
    [Parameter(Mandatory = $true)][int[]]$Ids,
    [string[]]$Fields = @('System.WorkItemType', 'System.TeamProject')
  )
  $map = @{}
  $unique = @($Ids | Where-Object { $_ } | Select-Object -Unique)
  for ($i = 0; $i -lt $unique.Count; $i += 200) {
    $batch = $unique[$i..([Math]::Min($i + 199, $unique.Count - 1))]
    $uri = $script:CoreBase + "_apis/wit/workitems?ids=" + ($batch -join ',') +
           "&fields=" + ($Fields -join ',') + "&errorPolicy=omit&api-version=$($script:ApiVersion)"
    $page = Invoke-AdoGet -Uri $uri
    foreach ($wi in @($page.value)) { $map[[int]$wi.id] = $wi.fields }
  }
  return $map
}

function Get-WorkItemRelations {
  # Relations (parent, child, Tested By, ...) for a set of IDs through the work items REST
  # API (GET, 200 IDs per call, $expand=relations). Hashtable keyed by ID; an item with no
  # relations maps to an empty array.
  param([Parameter(Mandatory = $true)][int[]]$Ids)
  $map = @{}
  $unique = @($Ids | Where-Object { $_ } | Select-Object -Unique)
  for ($i = 0; $i -lt $unique.Count; $i += 200) {
    $batch = $unique[$i..([Math]::Min($i + 199, $unique.Count - 1))]
    $uri = $script:CoreBase + "_apis/wit/workitems?ids=" + ($batch -join ',') +
           "&`$expand=relations&errorPolicy=omit&api-version=$($script:ApiVersion)"
    $page = Invoke-AdoGet -Uri $uri
    foreach ($wi in @($page.value)) { $map[[int]$wi.id] = if ($wi.relations) { @($wi.relations) } else { @() } }
  }
  return $map
}

function Get-WorkItemTypeFieldNames($Project, [string]$Type) {
  # Reference names of the fields on a work item type, cached per project and type. A type
  # the process does not have (User Story on Scrum) yields an empty list.
  if (-not $script:TypeFieldCache) { $script:TypeFieldCache = @{} }
  $key = "$($Project.id)|$Type"
  if (-not $script:TypeFieldCache.ContainsKey($key)) {
    $names = @()
    try {
      $r = Invoke-AdoGet -Uri ($script:CoreBase + "$($Project.id)/_apis/wit/workitemtypes/$([uri]::EscapeDataString($Type))/fields?api-version=$($script:ApiVersion)")
      $names = @($r.value | ForEach-Object { [string]$_.referenceName })
    } catch { }
    $script:TypeFieldCache[$key] = $names
  }
  return $script:TypeFieldCache[$key]
}

function Test-HasText([string]$Html) {
  # True when an HTML field holds something beyond tags, entities and whitespace.
  if ([string]::IsNullOrWhiteSpace($Html)) { return $false }
  $text = $Html -replace '<[^>]+>', '' -replace '&nbsp;', ' ' -replace '&#160;', ' '
  return -not [string]::IsNullOrWhiteSpace($text)
}

function Get-WorkItemUrl($Project, $Id) {
  return $script:CoreBase + [uri]::EscapeDataString($Project.name) + "/_workitems/edit/$Id"
}

function Get-Plural([string]$Type) {
  switch ($Type) { 'User Story' { 'User Stories' } 'Product Backlog Item' { 'Product Backlog Items' } default { $Type + 's' } }
}

function Format-Count([int]$Count, [string]$Singular, [string]$Plural = "") {
  if (-not $Plural) { $Plural = $Singular + "s" }
  if ($Count -eq 1) { return "1 $Singular" }
  return "$Count $Plural"
}

#######################################################################################################################################################################
#                                                                    RULES: CFG (project configuration)                                                              #
#######################################################################################################################################################################

function Get-AdoProcessMap {
  # Process typeId -> process object, with ParentName added for inherited processes.
  if (-not $script:ProcessMap) {
    $map = @{}
    $procs = Invoke-AdoGet -Uri ($script:CoreBase + "_apis/work/processes?api-version=$($script:ApiVersion)") -AllPages
    foreach ($p in $procs) { $map[[string]$p.typeId] = $p }
    foreach ($p in $procs) {
      $parentName = $null
      if ($p.parentProcessTypeId -and $map.ContainsKey([string]$p.parentProcessTypeId)) { $parentName = $map[[string]$p.parentProcessTypeId].name }
      $p | Add-Member -NotePropertyName ParentName -NotePropertyValue $parentName -Force
    }
    $script:ProcessMap = $map
  }
  return $script:ProcessMap
}

function Get-ProjectProcessName($Project) {
  # The (inherited) process the project is on, e.g. "Core Agile".
  $detail = Invoke-AdoGet -Uri ($script:CoreBase + "_apis/projects/$($Project.id)?includeCapabilities=true&api-version=$($script:ApiVersion)")
  $name = $null; $typeId = $null
  if ($detail.capabilities -and $detail.capabilities.processTemplate) {
    $name = [string]$detail.capabilities.processTemplate.templateName
    $typeId = [string]$detail.capabilities.processTemplate.templateTypeId
  }
  $map = Get-AdoProcessMap
  if ($typeId -and $map.ContainsKey($typeId)) { $name = [string]$map[$typeId].name }
  return $name
}

# Project services, by the feature id the Feature Management API uses.
# Feature ids behind Project settings, Overview. Artifacts is ms.azure-artifacts.feature;
# ms.feed.feed exists too but is never set by the toggle (always "undefined"), so reading
# it reports Artifacts as on in projects where it is off.
$script:ProjectServices = [ordered]@{
  'Boards'     = 'ms.vss-work.agile'
  'Repos'      = 'ms.vss-code.version-control'
  'Pipelines'  = 'ms.vss-build.pipelines'
  'Test Plans' = 'ms.vss-test-web.test'
  'Artifacts'  = 'ms.azure-artifacts.feature'
}

function Get-ProjectServiceStates($Project) {
  # Service name -> $true when enabled. "undefined" means the default, which is on.
  $states = [ordered]@{}
  foreach ($svc in $script:ProjectServices.Keys) {
    $fid = $script:ProjectServices[$svc]
    $r = Invoke-AdoGet -Uri ($script:CoreBase + "_apis/FeatureManagement/FeatureStates/host/project/$($Project.id)/$fid" + "?api-version=$($script:ApiVersion)-preview.1")
    $states[$svc] = ([string]$r.state -ne 'disabled')
  }
  return $states
}

function Get-ClassificationTree($Project, [string]$StructureType) {
  # The area or iteration tree, root node included, depth 50.
  $nodes = Invoke-AdoGet -Uri ($script:CoreBase + "$($Project.id)/_apis/wit/classificationnodes?`$depth=50&api-version=$($script:ApiVersion)")
  return @($nodes.value | Where-Object { $_.structureType -eq $StructureType })[0]
}

function Get-TreeNodes($Node, [string]$Path = "") {
  # Flattens a classification tree into (Path, Node, Depth, IsLeaf) rows, root excluded.
  $out = New-Object System.Collections.Generic.List[object]
  $walk = $null
  $walk = {
    param($n, $p, $d)
    if (-not $n.children) { return }   # @($null) would loop forever
    foreach ($c in @($n.children)) {
      $cp = if ($p) { "$p\$($c.name)" } else { [string]$c.name }
      $isLeaf = -not ($c.children -and @($c.children).Count -gt 0)
      $out.Add([pscustomobject]@{ Path = $cp; Node = $c; Depth = $d; IsLeaf = $isLeaf })
      & $walk $c $cp ($d + 1)
    }
  }
  & $walk $Node $Path 1
  return $out.ToArray()
}

function New-NodeItem($Project, $Row, [string]$Type, [string]$Problem) {
  [pscustomobject]@{
    Id = [int]$Row.Node.id; Type = $Type; Title = $Row.Path; State = ""; AreaPath = ""
    Problem = $Problem; ParentId = $null; ParentType = $null; Url = $null
  }
}

function New-NamedItem([string]$Type, [string]$Title, [string]$Problem, [string]$Url = $null, $Id = 0) {
  [pscustomobject]@{ Id = $Id; Type = $Type; Title = $Title; State = ""; AreaPath = ""; Problem = $Problem; ParentId = $null; ParentType = $null; Url = $Url }
}

function Get-ProjectModel {
  # ProjectModel setting: Standard (one project holds work and code; CFG000, CFG100, CFG110)
  # or HubSpoke (a hub holds the work items, spokes hold the code; CFG002, CFG004, CFG120
  # to CFG132). Each family of rules checks it belongs to the model in force.
  $model = [string](Get-Setting 'ProjectModel' 'Standard')
  if ($model -ieq 'HubSpoke') { return 'HubSpoke' }
  return 'Standard'
}

function Test-ProjectModel($Project, [string]$Code, [string]$Model) {
  # True when the rule belongs to the model in force; otherwise records a red row and
  # returns false, so a rules file with the wrong family switched on says so.
  $have = Get-ProjectModel
  if ($have -eq $Model) { return $true }
  Add-Result -Project $Project -Rule $Code -Status $script:StatusError `
    -Description "$Code belongs to the $Model project model, but ProjectModel is $have. Switch the rule off or change the setting." `
    -Note "Belongs to the $Model model; ProjectModel is $have"
  return $false
}

function Test-FirstTarget($Project) {
  # Organization-level rules read named projects from the settings rather than the project
  # being inspected, so they run once, with the first inspected project, not once per project.
  return ([string]$Project.id -eq [string]$script:Targets[0].id)
}

function Get-NamedProject([string]$Name) {
  # The project object for a name in the settings, or $null when the organization has none.
  return (Get-AdoAllProjects | Where-Object { [string]$_.name -ieq $Name } | Select-Object -First 1)
}

# ---- Organization: process (CFG000 Standard; CFG002 and CFG004 HubSpoke)
function Rule_CFG000_ProjectUsesExpectedProcess {
  # Standard model. The project named in Project (or every inspected project when Project
  # is empty) is on the ExpectedProcess process.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  if (-not (Test-ProjectModel $Project $code 'Standard')) { return }
  $named = [string](Get-Setting 'Project' '')
  $have = Get-ProjectProcessName $Project
  if ($named -and [string]$Project.name -ine $named) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "Not the named project ($named); $($Project.name) uses $have." -Note "Not the named project ($named); $($Project.name) uses $have"
    return
  }
  $want = [string](Get-Setting 'ExpectedProcess' '')
  if ([string]::IsNullOrWhiteSpace($want)) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "No ExpectedProcess setting in the rules file; $($Project.name) uses $have." -Note "No ExpectedProcess setting; $($Project.name) uses $have"
    return
  }
  if ($have -ieq $want) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "$($Project.name) uses $want." -Note "$($Project.name) uses $want"
  } else {
    Add-Result -Project $Project -Rule $code -Status $script:StatusWarning -Description "$($Project.name) uses $have, expected $want." -Note "$($Project.name) uses $have, expected $want" `
      -Items @(New-NamedItem 'Project' ([string]$Project.name) "Process is $have, expected $want")
  }
}

function Test-NamedProjectsProcess {
  # Shared by CFG002 and CFG004: every project named in the setting is on the expected
  # process. Runs once per run, not once per inspected project.
  param($Project, [string]$Code, [string]$ProjectSetting, [string]$ProcessSetting, [string]$Label, [string]$Plural)
  if (-not (Test-ProjectModel $Project $Code 'HubSpoke')) { return }
  if (-not (Test-FirstTarget $Project)) { return }
  $names = @(Get-SettingList $ProjectSetting @())
  $want = [string](Get-Setting $ProcessSetting '')
  if ($names.Count -eq 0) {
    Add-Result -Project $Project -Rule $Code -Status $script:StatusError -Description "No $ProjectSetting setting in the rules file; name the $Plural or switch $Code off." -Note "No $ProjectSetting setting"
    return
  }
  $items = New-Object System.Collections.Generic.List[object]
  $uses = @()
  foreach ($name in $names) {
    $p = Get-NamedProject $name
    if (-not $p) { $items.Add((New-NamedItem 'Project' $name "Not found in the organization (check $ProjectSetting or PAT access)")); continue }
    $have = Get-ProjectProcessName $p
    $uses += "$($p.name) uses $have"
    if ($want -and $have -ine $want) { $items.Add((New-NamedItem 'Project' ([string]$p.name) "Process is $have, expected $want")) }
  }
  $usesText = $uses -join ', '
  if ([string]::IsNullOrWhiteSpace($want) -and $items.Count -eq 0) {
    Add-Result -Project $Project -Rule $Code -Status $script:StatusPass -Description "No $ProcessSetting setting in the rules file; $usesText." -Note "No $ProcessSetting setting; $usesText"
    return
  }
  # "IT, Foo1, Foo2 all use Contoso Scrum" when they agree; otherwise each project by name.
  $processes = @($uses | ForEach-Object { ($_ -split ' uses ', 2)[1] } | Select-Object -Unique)
  $summary = if ($uses.Count -gt 1 -and $processes.Count -eq 1) { "$(($uses | ForEach-Object { ($_ -split ' uses ', 2)[0] }) -join ', ') all use $($processes[0])" } else { $usesText }
  if ($items.Count -eq 0) {
    Add-Result -Project $Project -Rule $Code -Status $script:StatusPass -Description "$summary." -Note $summary
    return
  }
  Add-Result -Project $Project -Rule $Code -Status $script:StatusWarning -Description "$summary; expected $want." -Note "$summary, expected $want" -Items $items.ToArray()
}

function Rule_CFG002_HubProjectUsesExpectedProcess {
  # HubSpoke model. The HubProject is on the ExpectedHubProcess process.
  param($Project)
  Test-NamedProjectsProcess -Project $Project -Code (Get-RuleCode $MyInvocation.MyCommand.Name) -ProjectSetting 'HubProject' -ProcessSetting 'ExpectedHubProcess' -Label 'hub' -Plural 'hub project'
}

function Rule_CFG004_SpokeProjectsUseExpectedProcess {
  # HubSpoke model. Every project in SpokeProjects is on the ExpectedSpokeProcess process.
  param($Project)
  Test-NamedProjectsProcess -Project $Project -Code (Get-RuleCode $MyInvocation.MyCommand.Name) -ProjectSetting 'SpokeProjects' -ProcessSetting 'ExpectedSpokeProcess' -Label 'spoke' -Plural 'spoke projects'
}

# ---- Project services (CFG100, CFG110 Standard; CFG120 to CFG132 HubSpoke)
function Resolve-ServiceNames($Project, [string]$Code, [string]$Setting) {
  # The comma-separated services in a setting with canonical casing, or $null after a red
  # row for a name that is not one of Boards, Repos, Pipelines, Test Plans, Artifacts.
  $known = @($script:ProjectServices.Keys)
  $expected = @(Get-SettingList $Setting @())
  $unknown = @($expected | Where-Object { $known -notcontains $_ })
  if ($unknown.Count -gt 0) {
    Add-Result -Project $Project -Rule $Code -Status $script:StatusError `
      -Description "Unknown service in ${Setting}: $($unknown -join ', '). Use: $($known -join ', ')." -Note "Unknown service in ${Setting}: $($unknown -join ', ')"
    return $null
  }
  return ,@($expected | ForEach-Object { $e = $_; $known | Where-Object { $_ -ieq $e } })
}

function Get-ServicesOn($Project, [string]$Code, $Target = $null) {
  # The services switched on in Target (the inspected Project when omitted), or $null after
  # a red row, recorded against the inspected project, when the API refuses.
  if ($null -eq $Target) { $Target = $Project }
  try {
    $states = Get-ProjectServiceStates $Target
  } catch {
    # The Feature Management API is gated by the vso.features scope, which the token page
    # never shows: a PAT without it gets a bare 401 whatever else is ticked (verified 24
    # Sep 2026). tools\Add-PatFeaturesScope.ps1 adds the scope to an existing PAT through
    # the PAT lifecycle API. Otherwise switch these rules off, or check the services in
    # Project settings, Overview, in the browser. README.md tells the whole story.
    Add-Result -Project $Project -Rule $Code -Status $script:StatusError `
      -Description "Cannot read the service states of $($Target.name) with this PAT ($($_.Exception.Message)). The Feature Management API needs the hidden vso.features scope; add it with tools\Add-PatFeaturesScope.ps1, or switch $Code off and check Project settings, Overview, in the browser." `
      -Note "PAT lacks the vso.features scope; see tools\Add-PatFeaturesScope.ps1"
    return $null
  }
  return ,@($states.Keys | Where-Object { $states[$_] })
}

function Format-ServicesOn($On) {
  if (@($On).Count -gt 0) { return (@($On) -join ', ') }
  return 'none'
}

function Test-StandardServicesRule {
  # Shared by CFG100 and CFG110. Standard model: the project named in Project (or every
  # inspected project) against ExpectedServices. Mode is Missing (listed but off) or Extra
  # (on but not listed).
  param($Project, [string]$Code, [string]$Mode)
  if (-not (Test-ProjectModel $Project $Code 'Standard')) { return }
  $named = [string](Get-Setting 'Project' '')
  $expected = Resolve-ServiceNames $Project $Code 'ExpectedServices'
  if ($null -eq $expected) { return }
  $on = Get-ServicesOn $Project $Code
  if ($null -eq $on) { return }
  $onText = Format-ServicesOn $on
  if ($named -and [string]$Project.name -ine $named) {
    Add-Result -Project $Project -Rule $Code -Status $script:StatusPass -Description "Not the named project ($named); services on: $onText." -Note "Not the named project ($named); $onText on"
    return
  }
  if ($expected.Count -eq 0) {
    Add-Result -Project $Project -Rule $Code -Status $script:StatusPass -Description "No ExpectedServices setting; services on: $onText." -Note "No ExpectedServices setting; $onText on"
    return
  }
  if ($Mode -eq 'Missing') {
    $missing = @($expected | Where-Object { $on -notcontains $_ })
    if ($missing.Count -eq 0) {
      Add-Result -Project $Project -Rule $Code -Status $script:StatusPass -Description "Every expected service is on: $($expected -join ', ')." -Note ($expected -join ', ')
      return
    }
    $items = @($missing | ForEach-Object { New-NamedItem 'Service' $_ 'In ExpectedServices but switched off' })
    Add-Result -Project $Project -Rule $Code -Status $script:StatusWarning `
      -Description "Services on: $onText. Expected: $($expected -join ', '). Missing: $($missing -join ', ')." -Note "Missing: $($missing -join ', ')" -Items $items
  } else {
    $extra = @($on | Where-Object { $expected -notcontains $_ })
    if ($extra.Count -eq 0) {
      Add-Result -Project $Project -Rule $Code -Status $script:StatusPass -Description "No unexpected services enabled; services on: $onText." -Note "No unexpected services enabled"
      return
    }
    $items = @($extra | ForEach-Object { New-NamedItem 'Service' $_ 'Enabled but not in ExpectedServices' })
    Add-Result -Project $Project -Rule $Code -Status $script:StatusWarning `
      -Description "Services on: $onText. Expected: $($expected -join ', '). Unexpected: $($extra -join ', ')." -Note "Unexpected: $($extra -join ', ')" -Items $items
  }
}

function Rule_CFG100_ProjectHasExpectedServicesEnabled {
  # Standard model. Every service in ExpectedServices is switched on in Project settings,
  # Overview. CFG110 is the other half: nothing outside the list is on.
  param($Project)
  Test-StandardServicesRule -Project $Project -Code (Get-RuleCode $MyInvocation.MyCommand.Name) -Mode 'Missing'
}

function Rule_CFG110_ProjectDoesNotHaveUnexpectedServicesEnabled {
  # Standard model. No service outside ExpectedServices is switched on. CFG100 is the
  # other half: everything in the list is on.
  param($Project)
  Test-StandardServicesRule -Project $Project -Code (Get-RuleCode $MyInvocation.MyCommand.Name) -Mode 'Extra'
}

function Test-NamedProjectsServicesRule {
  # Shared by CFG120 to CFG132. HubSpoke model: every project named in ProjectSetting
  # against the services in ServicesSetting. Runs once per run. Mode is Missing or Extra.
  param($Project, [string]$Code, [string]$ProjectSetting, [string]$ServicesSetting, [string]$Mode, [string]$Plural)
  if (-not (Test-ProjectModel $Project $Code 'HubSpoke')) { return }
  if (-not (Test-FirstTarget $Project)) { return }
  $names = @(Get-SettingList $ProjectSetting @())
  if ($names.Count -eq 0) {
    Add-Result -Project $Project -Rule $Code -Status $script:StatusError -Description "No $ProjectSetting setting in the rules file; name the $Plural or switch $Code off." -Note "No $ProjectSetting setting"
    return
  }
  $expected = Resolve-ServiceNames $Project $Code $ServicesSetting
  if ($null -eq $expected) { return }
  $items = New-Object System.Collections.Generic.List[object]
  $onTexts = @()
  foreach ($name in $names) {
    $p = Get-NamedProject $name
    if (-not $p) { $items.Add((New-NamedItem 'Project' $name "Not found in the organization (check $ProjectSetting or PAT access)")); continue }
    $on = Get-ServicesOn $Project $Code $p
    if ($null -eq $on) { return }   # the red row is recorded
    $onTexts += "$($p.name): $(Format-ServicesOn $on)"
    if ($expected.Count -eq 0) { continue }
    if ($Mode -eq 'Missing') {
      foreach ($s in @($expected | Where-Object { $on -notcontains $_ })) { $items.Add((New-NamedItem 'Service' "$($p.name): $s" "In $ServicesSetting but switched off in $($p.name)")) }
    } else {
      foreach ($s in @($on | Where-Object { $expected -notcontains $_ })) { $items.Add((New-NamedItem 'Service' "$($p.name): $s" "Enabled in $($p.name) but not in $ServicesSetting")) }
    }
  }
  $onSummary = $onTexts -join '; '
  if ($expected.Count -eq 0 -and $items.Count -eq 0) {
    Add-Result -Project $Project -Rule $Code -Status $script:StatusPass -Description "No $ServicesSetting setting; services on: $onSummary." -Note "No $ServicesSetting setting; $onSummary"
    return
  }
  if ($items.Count -eq 0) {
    $note = if ($Mode -eq 'Missing') { "$($expected -join ', ') on in $(Format-Count $names.Count 'project')" } else { "No unexpected services enabled in $(Format-Count $names.Count 'project')" }
    Add-Result -Project $Project -Rule $Code -Status $script:StatusPass -Description "$note; services on: $onSummary." -Note $note
    return
  }
  $what = if ($Mode -eq 'Missing') { 'expected service is off' } else { 'unexpected service is on' }
  $whats = if ($Mode -eq 'Missing') { 'expected services are off' } else { 'unexpected services are on' }
  Add-Result -Project $Project -Rule $Code -Status $script:StatusWarning `
    -Description ("{0} across the {1} ({2}). Services on: {3}." -f (Format-Count $items.Count $what $whats), $Plural, (($items | ForEach-Object { $_.Title }) -join ', '), $onSummary) `
    -Note ("{0}: {1}" -f (Format-Count $items.Count $what $whats), (($items | ForEach-Object { $_.Title }) -join ', ')) -Items $items.ToArray()
}

function Rule_CFG120_HubProjectHasExpectedServicesEnabled {
  # HubSpoke model. Every service in ExpectedHubServices is on in the HubProject.
  param($Project)
  Test-NamedProjectsServicesRule -Project $Project -Code (Get-RuleCode $MyInvocation.MyCommand.Name) -ProjectSetting 'HubProject' -ServicesSetting 'ExpectedHubServices' -Mode 'Missing' -Plural 'hub project'
}

function Rule_CFG122_HubProjectDoesNotHaveUnexpectedServicesEnabled {
  # HubSpoke model. Nothing outside ExpectedHubServices is on in the HubProject.
  param($Project)
  Test-NamedProjectsServicesRule -Project $Project -Code (Get-RuleCode $MyInvocation.MyCommand.Name) -ProjectSetting 'HubProject' -ServicesSetting 'ExpectedHubServices' -Mode 'Extra' -Plural 'hub project'
}

function Rule_CFG130_SpokeProjectsHaveExpectedServicesEnabled {
  # HubSpoke model. Every service in ExpectedSpokeServices is on in every SpokeProjects project.
  param($Project)
  Test-NamedProjectsServicesRule -Project $Project -Code (Get-RuleCode $MyInvocation.MyCommand.Name) -ProjectSetting 'SpokeProjects' -ServicesSetting 'ExpectedSpokeServices' -Mode 'Missing' -Plural 'spoke projects'
}

function Rule_CFG132_SpokeProjectsDoNotHaveUnexpectedServicesEnabled {
  # HubSpoke model. Nothing outside ExpectedSpokeServices is on in any SpokeProjects project.
  param($Project)
  Test-NamedProjectsServicesRule -Project $Project -Code (Get-RuleCode $MyInvocation.MyCommand.Name) -ProjectSetting 'SpokeProjects' -ServicesSetting 'ExpectedSpokeServices' -Mode 'Extra' -Plural 'spoke projects'
}

function Rule_CFG140_AreasDefined {
  # The area tree has nodes under the root.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $rows = Get-TreeNodes (Get-ClassificationTree $Project 'area')
  if ($rows.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusWarning -Description "No areas under the root; every item lands in the project root." -Note "No areas defined" `
      -Items @(New-NamedItem 'Area' ([string]$Project.name) 'Only the root area exists')
    return
  }
  $top = @($rows | Where-Object { $_.Depth -eq 1 })
  Add-Result -Project $Project -Rule $code -Status $script:StatusPass `
    -Description ("{0} defined, {1} directly under the root: {2}." -f (Format-Count $rows.Count 'area'), $top.Count, (($top | ForEach-Object { $_.Node.name }) -join ', ')) `
    -Note (Format-Count $rows.Count 'area defined' 'areas defined')
}

function Rule_CFG150_IterationsDefined {
  # The iteration tree has nodes under the root.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $rows = Get-TreeNodes (Get-ClassificationTree $Project 'iteration')
  if ($rows.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusWarning -Description "No iterations under the root." -Note "No iterations defined" `
      -Items @(New-NamedItem 'Iteration' ([string]$Project.name) 'Only the root iteration exists')
    return
  }
  $leaves = @($rows | Where-Object { $_.IsLeaf })
  Add-Result -Project $Project -Rule $code -Status $script:StatusPass `
    -Description ("{0} defined, {1} of them leaf nodes." -f (Format-Count $rows.Count 'iteration'), $leaves.Count) `
    -Note (Format-Count $rows.Count 'iteration defined' 'iterations defined')
}

function Rule_CFG155_IterationsFollowSafePiNaming {
  # The iteration tree is SAFe-shaped: PIs sit directly under the root and are named YY.N
  # (26.1), sprints sit under their PI and are named YY.N.M (26.1.2) with the PI's name as
  # the prefix, and nothing goes deeper. A PI with no sprints yet is fine.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $rows = @(Get-TreeNodes (Get-ClassificationTree $Project 'iteration'))
  if ($rows.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "No iterations under the root; nothing to check." -Note "No iterations to check"
    return
  }
  $items = @(foreach ($row in $rows) {
    $name = [string]$row.Node.name
    $problem = switch ($row.Depth) {
      1 { if ($name -notmatch '^\d{2}\.[1-9]\d?$') { "PI is not named YY.N" } }
      2 {
        $pi = $row.Path.Split('\')[-2]
        if ($name -notmatch '^\d{2}\.[1-9]\d?\.[1-9]\d?$') { "Sprint is not named YY.N.M" }
        elseif (-not $name.StartsWith("$pi.")) { "Sprint is not numbered under its PI $pi" }
      }
      default { "Nested deeper than PI and sprint" }
    }
    if ($problem) { New-NodeItem $Project $row 'Iteration' $problem }
  })
  $pis     = @($rows | Where-Object { $_.Depth -eq 1 }).Count
  $sprints = @($rows | Where-Object { $_.Depth -eq 2 }).Count
  Add-CountResult -Project $Project -RuleCode $code -Items $items `
    -PassNote ("Every iteration follows the SAFe pattern ({0}, {1})" -f (Format-Count $pis 'PI'), (Format-Count $sprints 'sprint')) `
    -Singular "iteration breaks the SAFe naming pattern" -Plural "iterations break the SAFe naming pattern"
}

function Rule_CFG157_SprintNamesFollowTheAgreedPattern {
  # Every sprint name matches the SprintNamePattern setting, a regular expression such as
  # ^Sprint (\d{3})$; the flat-list alternative to CFG155. When the pattern captures a
  # number, the numbers must run without gaps.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $pattern = [string](Get-Setting 'SprintNamePattern' '')
  if ([string]::IsNullOrWhiteSpace($pattern)) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "No SprintNamePattern setting in the rules file; nothing to check." -Note "No SprintNamePattern setting"
    return
  }
  $sprints = @(Get-DatedSprints $Project)
  if ($sprints.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "No dated sprints to check." -Note "No dated sprints to check"
    return
  }
  $items = New-Object System.Collections.Generic.List[object]
  $numbers = New-Object System.Collections.Generic.List[int]
  foreach ($s in $sprints) {
    $m = [regex]::Match([string]$s.Row.Node.name, $pattern)
    if (-not $m.Success) { $items.Add((New-NodeItem $Project $s.Row 'Iteration' "Name does not match $pattern")); continue }
    if ($m.Groups.Count -gt 1 -and $m.Groups[1].Value -match '^\d+$') { $numbers.Add([int]$m.Groups[1].Value) }
  }
  $gaps = @()
  if ($numbers.Count -gt 1) {
    $sorted = @($numbers | Sort-Object -Unique)
    for ($n = $sorted[0]; $n -le $sorted[-1]; $n++) { if ($sorted -notcontains $n) { $gaps += $n } }
    foreach ($g in $gaps) { $items.Add((New-NamedItem 'Iteration' "$g" "No sprint numbered $g between $($sorted[0]) and $($sorted[-1])")) }
  }
  $detail = if ($gaps.Count -gt 0) { "numbers skip $($gaps -join ', ')" } else { "" }
  Add-CountResult -Project $Project -RuleCode $code -Items $items -PassNote "Every sprint name matches the pattern ($($sprints.Count) checked)" `
    -Singular "sprint name or number breaks the pattern" -Plural "sprint names or numbers break the pattern" -Detail $detail
}

function Rule_CFG160_IterationsHaveDates {
  # Every sprint (leaf iteration) has a start and a finish date.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $leaves = @((Get-TreeNodes (Get-ClassificationTree $Project 'iteration')) | Where-Object { $_.IsLeaf })
  $items = @($leaves | Where-Object { -not ($_.Node.attributes -and $_.Node.attributes.startDate -and $_.Node.attributes.finishDate) } |
    ForEach-Object { New-NodeItem $Project $_ 'Iteration' 'No start or finish date' })
  Add-CountResult -Project $Project -RuleCode $code -Items $items -PassNote "Every sprint has dates ($($leaves.Count) checked)" `
    -Singular "sprint has no dates" -Plural "sprints have no dates"
}

function ConvertTo-UtcDate([string]$Value) {
  # Iteration dates arrive as ISO text with a Z. [datetime] would shift them to local time,
  # which moves a midnight start to the previous evening and so to the wrong weekday.
  return ([DateTimeOffset]$Value).UtcDateTime.Date
}

function Get-DatedSprints($Project) {
  # Every sprint in the iteration tree: a leaf with both dates spanning SprintMaxDays or
  # fewer. PI and release nodes are longer and so are left out. Shared by CFG157, CFG180 and CFG190.
  $max = [int](Get-Setting 'SprintMaxDays' 21)
  $leaves = @((Get-TreeNodes (Get-ClassificationTree $Project 'iteration')) | Where-Object { $_.IsLeaf -and $_.Node.attributes -and $_.Node.attributes.startDate -and $_.Node.attributes.finishDate })
  return @($leaves | ForEach-Object {
    $start = ConvertTo-UtcDate $_.Node.attributes.startDate
    $end   = ConvertTo-UtcDate $_.Node.attributes.finishDate
    [pscustomobject]@{ Row = $_; Start = $start; End = $end; Days = [int]($end - $start).TotalDays + 1 }
  } | Where-Object { $_.Days -le $max })
}

function Get-Norm($Values) {
  # The most common value in a list; ties go to the larger value so the answer is stable.
  return ($Values | Group-Object | Sort-Object Count, Name -Descending | Select-Object -First 1).Name
}

function Rule_CFG180_ConsistentIterationLengths {
  # Every sprint (a dated leaf iteration of SprintMaxDays or fewer) is the same number of
  # days. SprintLengthDays (setting) is the norm when given; otherwise the most common
  # length is. Sprints of any other length are flagged. PI nodes are longer than
  # SprintMaxDays and so are left out.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $dated = @(Get-DatedSprints $Project)
  if ($dated.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "No dated sprints to compare." -Note "No dated sprints to compare"
    return
  }
  $agreed = Get-Setting 'SprintLengthDays' $null
  $norm = if ($agreed) { [int]$agreed } else { Get-Norm ($dated | ForEach-Object { $_.Days }) }
  $basis = if ($agreed) { "the agreed length" } else { "the most common length" }
  $odd = @($dated | Where-Object { [string]$_.Days -ne [string]$norm })
  if ($odd.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "All $($dated.Count) dated sprints are $norm days long, $basis." -Note "All sprints are $norm days"
    return
  }
  $items = @($odd | ForEach-Object { New-NodeItem $Project $_.Row 'Iteration' "$($_.Days) days, not $norm" })
  $lengths = (($odd | ForEach-Object { $_.Days } | Sort-Object -Unique) -join ', ')
  Add-Result -Project $Project -Rule $code -Status $script:StatusWarning `
    -Description ("{0} of {1} dated sprints are not {2} days long, {3} ({4} days)." -f $odd.Count, $dated.Count, $norm, $basis, $lengths) `
    -Note ("{0} not {1} days ({2})" -f (Format-Count $odd.Count 'sprint is' 'sprints are'), $norm, $lengths) -Items $items
}

function Rule_CFG190_IterationsFollowTheSameCadence {
  # Every sprint starts on the same weekday and finishes on the same weekday, so the
  # calendar is one cadence: Wednesday to Tuesday, say, sprint after sprint. The most
  # common start and finish weekdays are the norm; any sprint off either is flagged.
  # CFG180 checks the length; together they say every sprint is the same shape.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $dated = @(Get-DatedSprints $Project)
  if ($dated.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "No dated sprints to compare." -Note "No dated sprints to compare"
    return
  }
  $startNorm = Get-Norm ($dated | ForEach-Object { [string]$_.Start.DayOfWeek })
  $endNorm   = Get-Norm ($dated | ForEach-Object { [string]$_.End.DayOfWeek })
  $items = @(foreach ($s in $dated) {
    $problems = @()
    if ([string]$s.Start.DayOfWeek -ne $startNorm) { $problems += "Starts $($s.Start.DayOfWeek) $($s.Start.ToString('yyyy-MM-dd')), not $startNorm" }
    if ([string]$s.End.DayOfWeek -ne $endNorm)     { $problems += "Ends $($s.End.DayOfWeek) $($s.End.ToString('yyyy-MM-dd')), not $endNorm" }
    if ($problems.Count -gt 0) { New-NodeItem $Project $s.Row 'Iteration' ($problems -join '; ') }
  })
  $cadence = "$startNorm to $endNorm"
  if ($items.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "All $($dated.Count) dated sprints run $cadence." -Note "All sprints run $cadence"
    return
  }
  Add-Result -Project $Project -Rule $code -Status $script:StatusWarning `
    -Description ("{0} of {1} dated sprints do not run {2}." -f $items.Count, $dated.Count, $cadence) `
    -Note ("{0} off the {1} cadence" -f (Format-Count $items.Count 'sprint is' 'sprints are'), $cadence) -Items $items
}


# ---- Teams
function Get-AdoTeams($Project) {
  # The project's teams, cached per project.
  if (-not $script:TeamCache) { $script:TeamCache = @{} }
  $key = [string]$Project.id
  if (-not $script:TeamCache.ContainsKey($key)) {
    $rows = Invoke-AdoGet -Uri ($script:CoreBase + "_apis/projects/$($Project.id)/teams?`$top=500&api-version=$($script:ApiVersion)") -AllPages
    $script:TeamCache[$key] = @($rows)
  }
  # Assign the result, as with Get-AnalyticsWorkItems; @(Get-AdoTeams ...) would nest the array.
  return ,$script:TeamCache[$key]
}

function Get-AdoTeamMembers($Project, $Team) {
  # Assign the result; @(Get-AdoTeamMembers ...) would nest the array.
  $rows = Invoke-AdoGet -Uri ($script:CoreBase + "_apis/projects/$($Project.id)/teams/$($Team.id)/members?`$top=500&api-version=$($script:ApiVersion)") -AllPages
  return ,@($rows)
}

function Get-TeamNameSets($Project) {
  # The project's team names and the ExpectedTeams setting, compared case-insensitively.
  $teams = Get-AdoTeams $Project
  $names = @($teams | ForEach-Object { [string]$_.name } | Sort-Object)
  $expected = @(Get-SettingList 'ExpectedTeams' @())
  return @{
    Names    = $names
    Expected = $expected
    Missing  = @($expected | Where-Object { $e = $_; -not ($names | Where-Object { $_ -ieq $e }) })
    Extra    = @($names | Where-Object { $n = $_; -not ($expected | Where-Object { $_ -ieq $n }) })
  }
}

function Rule_CFG305_ExpectedTeamsArePresent {
  # Every team in the ExpectedTeams setting exists in the project. CFG307 is the other
  # half: nothing outside the list exists.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $sets = Get-TeamNameSets $Project
  if ($sets.Expected.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass `
      -Description "No ExpectedTeams setting; $(Format-Count $sets.Names.Count 'team'): $($sets.Names -join ', ')." -Note "No ExpectedTeams setting; $(Format-Count $sets.Names.Count 'team')"
    return
  }
  $items = @($sets.Missing | ForEach-Object { New-NamedItem 'Team' $_ 'In ExpectedTeams but not in the project' })
  Add-CountResult -Project $Project -RuleCode $code -Items $items -PassNote "Every expected team is present ($($sets.Expected.Count) checked)" `
    -Singular "expected team is missing" -Plural "expected teams are missing" -Detail ($sets.Missing -join ', ')
}

function Rule_CFG307_NoUnexpectedTeamsPresent {
  # No team exists outside the ExpectedTeams setting; sub-groups that only need a filter
  # are area paths, not teams. CFG305 is the other half.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $sets = Get-TeamNameSets $Project
  if ($sets.Expected.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass `
      -Description "No ExpectedTeams setting; $(Format-Count $sets.Names.Count 'team'): $($sets.Names -join ', ')." -Note "No ExpectedTeams setting; $(Format-Count $sets.Names.Count 'team')"
    return
  }
  $items = @($sets.Extra | ForEach-Object { New-NamedItem 'Team' $_ 'In the project but not in ExpectedTeams' })
  Add-CountResult -Project $Project -RuleCode $code -Items $items -PassNote "No unexpected teams ($($sets.Names.Count) present)" `
    -Singular "unexpected team is present" -Plural "unexpected teams are present" -Detail ($sets.Extra -join ', ')
}

function Rule_CFG315_TeamsAreNotOversized {
  # No team has more than TeamMaxMembers (setting, 10); a team of 15 is two teams.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $max = [int](Get-Setting 'TeamMaxMembers' 10)
  $teams = Get-AdoTeams $Project
  $sizes = @(foreach ($team in $teams) {
    $members = Get-AdoTeamMembers $Project $team
    [pscustomobject]@{ Team = [string]$team.name; Count = @($members).Count }
  })
  $sizes = @($sizes | Sort-Object Count -Descending)
  if ($sizes.Count -eq 0) {
    Add-Result -Project $Project -Rule $code -Status $script:StatusPass -Description "No teams in the project." -Note "No teams"
    return
  }
  $items = @($sizes | Where-Object { $_.Count -gt $max } | ForEach-Object { New-NamedItem 'Team' $_.Team "$($_.Count) members, limit $max" })
  Add-CountResult -Project $Project -RuleCode $code -Items $items `
    -PassNote "No team has more than $max members (largest: $($sizes[0].Team) with $($sizes[0].Count))" `
    -Singular "team has more than $max members" -Plural "teams have more than $max members" `
    -Detail (($sizes | ForEach-Object { "$($_.Team): $($_.Count)" }) -join ', ')
}

function Rule_CFG335_EveryAreaIsCoveredByATeam {
  # Every area, the root included, is selected by at least one team, directly or through a
  # parent area selected with "include sub areas"; otherwise work there is on no backlog or
  # board. Reads each team's area settings (teamfieldvalues).
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $root = [string]$Project.name
  $areas = @($root) + @(Get-TreeNodes (Get-ClassificationTree $Project 'area') | ForEach-Object { "$root\$($_.Path)" })
  $covered = New-Object System.Collections.Generic.List[object]
  foreach ($team in (Get-AdoTeams $Project)) {
    $tfv = Invoke-AdoGet -Uri ($script:CoreBase + "$($Project.id)/$($team.id)/_apis/work/teamsettings/teamfieldvalues?api-version=$($script:ApiVersion)")
    foreach ($v in @($tfv.values)) { $covered.Add([pscustomobject]@{ Path = [string]$v.value; Children = [bool]$v.includeChildren }) }
  }
  $items = @(foreach ($a in $areas) {
    $hit = $covered | Where-Object { $_.Path -ieq $a -or ($_.Children -and $a.StartsWith("$($_.Path)\", [System.StringComparison]::OrdinalIgnoreCase)) }
    if (-not $hit) { New-NamedItem 'Area' $a 'No team selects this area' }
  })
  Add-CountResult -Project $Project -RuleCode $code -Items $items -PassNote "Every area is covered by a team ($($areas.Count) checked)" `
    -Singular "area has no team" -Plural "areas have no team" -Detail (($items | ForEach-Object { $_.Title }) -join ', ')
}


#######################################################################################################################################################################
#                                                        RULES: WRK 1xx to 5xx (Epics, Features, Stories, Bugs, Tasks)                                                  #
#######################################################################################################################################################################

function New-TypeFilter([string[]]$Types) {
  # OData filter matching any of the given work item types.
  return "(" + (($Types | ForEach-Object { "WorkItemType eq '$(ConvertTo-ODataString $_)'" }) -join ' or ') + ")"
}

function Get-OpenFilter {
  # OData filter fragment excluding the IgnoreStateCategories setting (default Completed, Removed).
  # Analytics gives items in a Removed state a null StateCategory, and its "ne" follows SQL
  # rules, so "StateCategory ne 'Removed'" drops them too. Get-RemovedFilter is the positive
  # form; "StateCategory eq 'Removed'" alone matches nothing.
  $f = ""
  foreach ($category in (Get-SettingList 'IgnoreStateCategories' @('Completed', 'Removed'))) {
    $f += " and StateCategory ne '$(ConvertTo-ODataString $category)'"
  }
  return $f
}

function Get-RemovedFilter {
  # OData filter fragment matching items in a Removed state (see Get-OpenFilter for why null).
  return "(StateCategory eq 'Removed' or StateCategory eq null)"
}

# The work item types the hierarchy rules look at, top to bottom.
$script:HierarchyTypes = @('Epic', 'Feature', 'User Story', 'Product Backlog Item', 'Bug', 'Task')

function Test-ParentRule {
  # Shared check behind the hierarchy rules: every open item of the child type(s) has a
  # parent, and that parent is one of the allowed type(s). Reads the children from
  # Analytics with the plain ParentWorkItemId column, then resolves parent types through
  # the work items REST API so parents in other projects count. Items in the
  # IgnoreStateCategories setting (default Completed, Removed) are skipped.
  param(
    [Parameter(Mandatory = $true)]$Project,
    [Parameter(Mandatory = $true)][string]$RuleCode,
    [Parameter(Mandatory = $true)][string[]]$ChildTypes,
    [Parameter(Mandatory = $true)][string]$Singular,
    [Parameter(Mandatory = $true)][string]$Plural,
    [Parameter(Mandatory = $true)][string[]]$ParentTypes,
    [Parameter(Mandatory = $true)][string]$ParentLabel,
    [switch]$AllowNoParent   # no parent is fine; only a parent of the wrong type is flagged
  )

  $filter = (New-TypeFilter $ChildTypes) + (Get-OpenFilter)
  $article = if ($ParentLabel -match '^[AEIOaeio]') { 'an' } else { 'a' }   # "an Epic", "a User Story"

  $children = Get-AnalyticsWorkItems -Project $Project -Filter $filter `
    -Select "WorkItemId,Title,WorkItemType,State,ParentWorkItemId" `
    -Expand "Area(`$select=AreaPath)"

  if ($children.Count -eq 0) {
    if ($AllowNoParent) {
      Add-Result -Project $Project -Rule $RuleCode -Status $script:StatusPass `
        -Description "No $Plural with a wrong parent; there are no open $Plural in this project." -Note "No open $Plural"
    } else {
      Add-Result -Project $Project -Rule $RuleCode -Status $script:StatusPass `
        -Description "No orphaned $Plural; there are no open $Plural in this project." -Note "No open, orphaned $Plural"
    }
    return
  }

  $parentIds = @($children | ForEach-Object { $_.ParentWorkItemId } | Where-Object { $_ } | ForEach-Object { [int]$_ })
  $parents = @{}
  if ($parentIds.Count -gt 0) { $parents = Get-WorkItemFields -Ids $parentIds }

  $items = New-Object System.Collections.Generic.List[object]
  foreach ($c in $children) {
    $problem = $null
    $parentId = $null
    $parentType = $null
    if ($c.ParentWorkItemId) {
      $parentId = [int]$c.ParentWorkItemId
      if ($parents.ContainsKey($parentId)) {
        $parentType = [string]$parents[$parentId].'System.WorkItemType'
        if ($ParentTypes -notcontains $parentType) { $problem = "Parent is a $parentType" }
      } else {
        $parentType = "unreadable"
        $problem = "Parent not readable by this PAT"
      }
    } elseif (-not $AllowNoParent) {
      $problem = "No parent"
    }
    if ($problem) {
      $items.Add([pscustomobject]@{
        Id         = [int]$c.WorkItemId
        Type       = [string]$c.WorkItemType
        Title      = [string]$c.Title
        State      = [string]$c.State
        AreaPath   = if ($c.Area) { [string]$c.Area.AreaPath } else { "" }
        Problem    = $problem
        ParentId   = $parentId
        ParentType = $parentType
        Url        = Get-WorkItemUrl $Project $c.WorkItemId
      })
    }
  }

  $total = Format-Count $children.Count "open $Singular" "open $Plural"
  if ($items.Count -eq 0) {
    if ($AllowNoParent) {
      Add-Result -Project $Project -Rule $RuleCode -Status $script:StatusPass `
        -Description "All $total have no parent or a parent $ParentLabel." -Note "No $Plural with a wrong parent"
    } else {
      Add-Result -Project $Project -Rule $RuleCode -Status $script:StatusPass `
        -Description "No orphaned $Plural; all $total have a parent $ParentLabel." -Note "No orphaned $Plural"
    }
    return
  }

  $noParent    = @($items | Where-Object { $_.Problem -eq 'No parent' }).Count
  $unreadable  = @($items | Where-Object { $_.ParentType -eq 'unreadable' }).Count
  $wrongParent = @($items | Where-Object { $_.Problem -like 'Parent is a *' })
  $parts = @()
  if ($noParent -gt 0) { $parts += "$noParent with no parent" }
  if ($wrongParent.Count -gt 0) {
    $byType = $wrongParent | Group-Object ParentType | Sort-Object Name | ForEach-Object { "$($_.Name): $($_.Count)" }
    $parts += "$($wrongParent.Count) with a parent that is not $article $ParentLabel ($($byType -join ', '))"
  }
  if ($unreadable -gt 0) { $parts += "$unreadable with a parent this PAT cannot read" }

  $found = if ($items.Count -eq 1) { "$Singular found" } else { "$Plural found" }
  if ($AllowNoParent) {
    $description = "{0} with a parent that is not {1} {2}: {3} of {4} ({5})." -f $found, $article, $ParentLabel, $items.Count, $total, ($parts -join '; ')
    $has = if ($items.Count -eq 1) { "has" } else { "have" }
    $note = "{0} {1} a parent that is not {2} {3}" -f (Format-Count $items.Count "open $Singular" "open $Plural"), $has, $article, $ParentLabel
  } else {
    $description = "{0} without parent {1}: {2} of {3} ({4})." -f $found, $ParentLabel, $items.Count, $total, ($parts -join '; ')
    $lack = if ($items.Count -eq 1) { "lacks" } else { "lack" }
    $note = "{0} {1} a parent {2}" -f (Format-Count $items.Count "open $Singular" "open $Plural"), $lack, $ParentLabel
  }
  Add-Result -Project $Project -Rule $RuleCode -Status $script:StatusWarning -Description $description -Note $note -Items ($items | Sort-Object Problem, Id)
}

# ---- Parent rules, one per type
function Rule_WRK100_NoEpicsWithAParent {
  # Nothing sits above Epic (D3): no open Epic has a parent of any type.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $rows = Get-AnalyticsWorkItems -Project $Project -Filter ((New-TypeFilter 'Epic') + (Get-OpenFilter)) `
    -Select "WorkItemId,Title,WorkItemType,State,ParentWorkItemId" -Expand "Area(`$select=AreaPath)"
  $withParent = @($rows | Where-Object { $_.ParentWorkItemId })
  $parents = @{}
  if ($withParent.Count -gt 0) { $parents = Get-WorkItemFields -Ids @($withParent | ForEach-Object { [int]$_.ParentWorkItemId }) -Fields @('System.WorkItemType') }
  $items = @(foreach ($w in $withParent) {
    $pid_ = [int]$w.ParentWorkItemId
    $ptype = if ($parents.ContainsKey($pid_)) { [string]$parents[$pid_].'System.WorkItemType' } else { 'item this PAT cannot read' }
    $row = New-WorkItemRow $Project $w "Parent is $ptype $pid_"
    $row.ParentId = $pid_; $row.ParentType = $ptype
    $row
  })
  Add-CountResult -Project $Project -RuleCode $code -Items $items -PassNote "No Epics with a parent ($($rows.Count) checked)" `
    -Singular "open Epic has a parent" -Plural "open Epics have a parent"
}

function Rule_WRK200_FeaturesHaveParentEpic {
  # Every open Feature has a parent, and that parent is an Epic (D4).
  param($Project)
  Test-ParentRule -Project $Project -RuleCode (Get-RuleCode $MyInvocation.MyCommand.Name) `
    -ChildTypes 'Feature' -Singular 'Feature' -Plural 'Features' `
    -ParentTypes 'Epic' -ParentLabel 'Epic'
}

function Rule_WRK300_StoriesHaveParentFeature {
  # Every open User Story (or Product Backlog Item, once the hub is on Scrum) has a
  # parent, and that parent is a Feature (D4).
  param($Project)
  Test-ParentRule -Project $Project -RuleCode (Get-RuleCode $MyInvocation.MyCommand.Name) `
    -ChildTypes 'User Story', 'Product Backlog Item' -Singular 'User Story' -Plural 'User Stories' `
    -ParentTypes 'Feature' -ParentLabel 'Feature'
}

function Rule_WRK305_StoriesAreNotDirectChildrenOfAnEpic {
  # No open User Story or Product Backlog Item has an Epic as its parent; a Feature always
  # sits between them. WRK300 counts these among its wrong parents; this rule names them alone.
  param($Project)
  $code = Get-RuleCode $MyInvocation.MyCommand.Name
  $rows = Get-AnalyticsWorkItems -Project $Project -Filter ((New-TypeFilter $script:StoryTypes) + (Get-OpenFilter) + " and ParentWorkItemId ne null") `
    -Select "WorkItemId,Title,WorkItemType,State,ParentWorkItemId" -Expand "Area(`$select=AreaPath)"
  $parents = @{}
  if ($rows.Count -gt 0) { $parents = Get-WorkItemFields -Ids @($rows | ForEach-Object { [int]$_.ParentWorkItemId }) -Fields @('System.WorkItemType') }
  $items = @(foreach ($w in $rows) {
    $pid_ = [int]$w.ParentWorkItemId
    if ($parents.ContainsKey($pid_) -and [string]$parents[$pid_].'System.WorkItemType' -eq 'Epic') {
      $row = New-WorkItemRow $Project $w "Parent is Epic $pid_"
      $row.ParentId = $pid_; $row.ParentType = 'Epic'
      $row
    }
  })
  Add-CountResult -Project $Project -RuleCode $code -Items $items -PassNote "No Stories directly under an Epic ($($rows.Count) with a parent checked)" `
    -Singular "open Story sits directly under an Epic" -Plural "open Stories sit directly under an Epic" -Detail (Get-TypeCounts $items)
}

function Rule_WRK400_BugsHaveParent {
  # Every open Bug has a parent, and that parent is a Feature or a User Story (D16).
